class ConfigModeloNomina extends BaseConfigModeloNomina
{

    /**
     * Obtener la configuraci�n de los modelos de nominas.
     *
     * @return array    Listado de configuraci�n de los modelos de nominas.
     */
    public static function obtenerConfigModelosNomina()
    {

        //Devolviendo el listado de configuraci�n de las variables globales en forma de arreglo.
        return Doctrine_Query::create()
            ->select('tn.idtiponomina ,tn.denominacion as denomtiponomina,
                   cmn.idconfmodelonomina as idconfmodelonomina, cmn.idtipopago as idtipopago, tp.denominacion as denomtipopago')
            ->from('NomTipoNomina tn')
            ->leftjoin('tn.ConfigModeloNomina cmn')
            ->leftjoin('cmn.NomTipoPago tp')
            ->orderBy('tn.denominacion ASC')
            ->fetchArray();
    }

    /**
     * Obtener un configuraci�n dado el identificador.
     *
     * @param int $idconfig Identificador de la configuraci�n.
     * @return ConfigModeloNomina            Objeto configuraci�n de modelos de n�mina (clase del dominio).
     */
    public static function obtenerObjConfigModelosNominaDadoId($idconfig)
    {
        return Doctrine::getTable('ConfigModeloNomina')->find($idconfig);
    }

    public static function obtenerIdNominaDagoConfig($idconfig)
    {
        $result = Doctrine_Query::create()
            ->select('idtiponomina')
            ->from('ConfigModeloNomina p')
            ->where("p.idconfmodelonomina=?", array($idconfig))
            ->fetchOne()
            ->idtiponomina;
        return $result;
    }

    public static function existeObjConfigModelosNominaDadoId($idtiponomina)
    {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('ConfigModeloNomina p')
            ->where("p.idtiponomina=?", array($idtiponomina))
            ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
            ->execute();
        if (count($result)) {
            return 1;
        } else {
            return 2;
        }
    }

    public static function dameIdTipoPagoDadoId($idtiponomina)
    {
        return Doctrine_Query::create()->select('p.idtipopago AS idtipopago')
            ->from('ConfigModeloNomina p')
            ->where('p.idtiponomina = ?', array($idtiponomina))
            ->fetchOne()
            ->idtipopago;
    }

    public static function obtenerConfigModelosNominaporTipoPago($idtipopago)
    {
        return Doctrine_Query::create()
            ->select('tn.idtiponomina, tn.denominacion as tiponomina, tn.liquidavacaciones,
                   cmn.idconfmodelonomina as idconfmodelonomina, cmn.idtipopago as idtipopago, tp.denominacion as tipopago, tn.acumulavacaciones as acumulavacaciones')
            ->from('NomTipoNomina tn')
            ->leftjoin('tn.ConfigModeloNomina cmn')
            ->leftjoin('cmn.NomTipoPago tp')
            ->where("cmn.idtipopago=?", array($idtipopago))
            ->fetchArray();
    }

    public static function obtenerIdTiposNominaporTipoPago($idelaborarpago)
    {
        $sql = "select cmn.idtiponomina as idtiponomina, cmn.idconfmodelonomina, ntn.denominacion
					from mod_nomina.conf_modelonomina cmn
					inner join mod_nomina.dat_elaborarpagos ep on (ep.idtipopago = cmn.idtipopago)
					inner join mod_nomina.nom_tiponomina ntn on (ntn.idtiponomina = cmn.idtiponomina)
					where ep.idelaborarpagos = ?;";

        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        return $conn->fetchAll($sql, array($idelaborarpago));
    }

    public static function obtenerIdCategoriasPersonalPorTipoPago($idtipopago)
    {
        $sql = "select idcategoria
					from mod_nomina.conf_modelonominacategoria cmnc
					inner join mod_nomina.conf_modelonomina cmn on (cmn.idconfmodelonomina = cmnc.idconfmodelonomina)
					where cmn.idtipopago = ?;";

        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        return $conn->fetchAll($sql, array($idtipopago));
    }

    public static function getNomCategorias() {
	    $sql = "select pc.idcategoriapersona,pc.denominacion as denom
					from mod_personaext.nom_categoriapersona pc;";

		$mg = Doctrine_Manager::getInstance();
		$conn = $mg->getCurrentConnection();
		return $conn->fetchAll($sql);
    }
}
